effect.shader:
void main() {
    int from = -max(1,int(softness));
    int to = max(1,int(softness));

    vec2 imgSize = getTexSize(inputImg.size);
    float px = (1.0/imgSize.x);
    float py = (1.0/imgSize.y);

    float ang = radians(direction);
    vec2 offs = vec2(cos(ang), sin(ang)) * distance;

    if (acPass == 0) {
        float nearestOutside = softness * 2.0;
        for (int i = from; i < to; i++) {
            vec4 inColor = texture2DCv(inputImg.texture, vec2(acScreenNorm.s + float(i) * px + offs.x * px, acScreenNorm.t));
            float xdistOut = inColor.a > 0.0 ? abs(float(i)) : softness * 2.0;
            nearestOutside = min(nearestOutside, xdistOut);
        }
        gl_FragColor = vec4(nearestOutside / max(0.0001,softness), 0.0, 0.0, 1.0);
    } else {
        float tOut = 2.0;
        for (int i = from; i < to; i++) {
            vec4 inColor = texture2DCv(hdist.texture, vec2(acScreenNorm.s, acScreenNorm.t + float(i) * py + offs.y * py));
            float xdistOut = inColor.r;
            float ydist = abs(float(i)) / max(0.0001,softness);
            float distOut = length(vec2(xdistOut, ydist));
            tOut = min(tOut, distOut);
        }
        vec4 original = texture2DCv(inputImg.texture, acScreenNorm.st);
        vec4 baseShadow = vec4(shadowColor.rgb, shadowAlpha);
        vec4 outColor = mix(baseShadow, vec4(0.0), smoothstep(0.0, 1.0, tOut));
        if (shadowOnly) {
            gl_FragColor = outColor;
        } else {
            vec4 result = original + outColor * (1.0 - original.a);
            gl_FragColor = result;
        }
    }
}
